const hash=name=>`CONVERT(varchar(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(${name}))),2)`;
const exact=value=>`CONVERT(varchar(60),CONVERT(decimal(28,8),${value}))`;
const equal=(a,b)=>`NOT EXISTS(SELECT ${a} EXCEPT SELECT ${b})`;
