  const registryImmutableSQL=`CREATE TRIGGER ${BUSINESS_PRICE_IMMUTABLE} ON ${BUSINESS_PRICE_REGISTRY} WITH EXECUTE AS OWNER AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON;
IF IS_SRVROLEMEMBER(N'sysadmin',ORIGINAL_LOGIN())<>1 OR DB_NAME() COLLATE Latin1_General_100_BIN2<>${lit(copy.target.database)} OR CONVERT(nvarchar(128),SERVERPROPERTY('ServerName')) COLLATE Latin1_General_100_BIN2<>${lit(copy.target.server)} OR EXISTS(SELECT 1 FROM deleted) OR(SELECT COUNT(*) FROM inserted)<>9 OR(SELECT COUNT(*) FROM ${BUSINESS_PRICE_REGISTRY})<>9 OR EXISTS(SELECT 1 FROM inserted WHERE copy_id<>${lit(copy.copyId)} OR revision<>12 OR base_seal_hash<>${lit(copy.sealHash)} OR base_revision_hash<>${lit(baseRevision.revisionHash)} OR profile_hash<>${lit(profileHash)} OR(kind='MODULE' AND name NOT IN(${BUSINESS_PRICE_MODULES.map(lit).join(',')})) OR(kind='SCHEMA' AND name NOT IN(${BUSINESS_PRICE_TABLES.map(lit).join(',')})) OR DATALENGTH(after_hash)<>64 OR after_hash COLLATE Latin1_General_100_BIN2 LIKE '%[^A-F0-9]%' OR DATALENGTH(revision_hash)<>64 OR revision_hash COLLATE Latin1_General_100_BIN2 LIKE '%[^A-F0-9]%') OR(SELECT COUNT(DISTINCT revision_hash) FROM inserted)<>1 ${error('REGISTRY_IMMUTABLE')}END;`;
